#!/usr/bin/env bash
TOKEN_FILE=/etc/nexup-bridge/hermes-session-token
HERMES_PROFILE=saieed
ALLOWED_PROFILES=saieed
token_value() {
  token="$(cat "$TOKEN_FILE")"
  printf '%s' "$token"
}
start_serve() {
  HERMES_DASHBOARD_SESSION_TOKEN="$1" "$DOCKER" exec -d -e HERMES_DASHBOARD_SESSION_TOKEN "$HERMES_CONTAINER" "$HERMES_BIN" -p "$HERMES_PROFILE" serve --isolated
}
recreate_bridge() {
  "$DOCKER" rm -f "$BRIDGE_CONTAINER"
  "$DOCKER" compose -f "$COMPOSE_FILE" up -d
}
